import bpy

lines=[]
lines.append(f'FILEPATH={bpy.data.filepath!r}')
lines.append('SCENES:')
for s in bpy.data.scenes:
    try:
        lines.append(f'- {s.name}: objects={len(s.objects)} children={[c.name for c in s.collection.children]}')
    except Exception as e:
        lines.append(f'- {s.name}: error={e}')
lines.append('WINDOWS:')
wm=bpy.context.window_manager
for i,w in enumerate(wm.windows):
    try:
        lines.append(f'- window[{i}] scene={w.scene.name} workspace={w.workspace.name} screen={w.screen.name}')
    except Exception as e:
        lines.append(f'- window[{i}] error={e}')
lines.append(f'CONTEXT_SCENE={bpy.context.scene.name}')
lines.append(f'CONTEXT_WINDOW_SCENE={getattr(getattr(bpy.context, "window", None), "scene", None).name if getattr(bpy.context, "window", None) else None}')
print('\n'.join(lines))
